CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT UNIQUE NOT NULL,username TEXT UNIQUE COLLATE NOCASE,pw TEXT,gsub TEXT UNIQUE,created INTEGER NOT NULL,pub TEXT NOT NULL DEFAULT '{}',shared TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS sessions(h TEXT PRIMARY KEY,uid INTEGER NOT NULL,exp INTEGER NOT NULL,csrf TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sess_uid ON sessions(uid);
CREATE TABLE IF NOT EXISTS friends(a INTEGER NOT NULL,b INTEGER NOT NULL,status TEXT NOT NULL,PRIMARY KEY(a,b));
CREATE INDEX IF NOT EXISTS fr_b ON friends(b);
CREATE TABLE IF NOT EXISTS saves(uid INTEGER NOT NULL,pack TEXT NOT NULL,data TEXT NOT NULL,xp INTEGER NOT NULL,upd INTEGER NOT NULL,PRIMARY KEY(uid,pack));
CREATE TABLE IF NOT EXISTS weekly(uid INTEGER NOT NULL,wk TEXT NOT NULL,xp INTEGER NOT NULL,PRIMARY KEY(uid,wk));
CREATE TABLE IF NOT EXISTS rl(k TEXT PRIMARY KEY,w INTEGER NOT NULL,n INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rooms(code TEXT PRIMARY KEY,mode TEXT NOT NULL,pack TEXT NOT NULL,host TEXT NOT NULL,qids TEXT NOT NULL,lims TEXT NOT NULL,state TEXT NOT NULL,qi INTEGER NOT NULL DEFAULT -1,qat INTEGER NOT NULL DEFAULT 0,rat INTEGER NOT NULL DEFAULT 0,bots INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL,exp INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS rooms_exp ON rooms(exp);
CREATE TABLE IF NOT EXISTS room_players(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT NOT NULL,nick TEXT NOT NULL COLLATE NOCASE,tok TEXT NOT NULL,av TEXT NOT NULL DEFAULT 'a0',score INTEGER NOT NULL DEFAULT 0,right INTEGER NOT NULL DEFAULT 0,streak INTEGER NOT NULL DEFAULT 0,bot INTEGER NOT NULL DEFAULT 0,acc REAL NOT NULL DEFAULT 0,spd REAL NOT NULL DEFAULT 0,seen INTEGER NOT NULL DEFAULT 0,UNIQUE(code,nick));
CREATE INDEX IF NOT EXISTS rp_tok ON room_players(code,tok);
CREATE TABLE IF NOT EXISTS room_answers(code TEXT NOT NULL,pid INTEGER NOT NULL,qi INTEGER NOT NULL,ok INTEGER NOT NULL,ms INTEGER NOT NULL,pts INTEGER NOT NULL,PRIMARY KEY(code,pid,qi));
CREATE TABLE IF NOT EXISTS vs_queue(th TEXT PRIMARY KEY,pack TEXT NOT NULL,nick TEXT NOT NULL,av TEXT NOT NULL,qids TEXT NOT NULL,lims TEXT NOT NULL,lvl REAL NOT NULL,bav TEXT NOT NULL,t INTEGER NOT NULL,match TEXT);
CREATE INDEX IF NOT EXISTS vq_pack ON vs_queue(pack,t);
